--
-- Table structure for table `PurchaseItems`
--

DROP TABLE IF EXISTS `PurchaseItems`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `PurchaseItems` (
  `id` int NOT NULL AUTO_INCREMENT,
  `purchaseId` int NOT NULL,
  `productId` int DEFAULT NULL,
  `productName` varchar(255) NOT NULL,
  `sku` varchar(255) DEFAULT NULL,
  `quantity` decimal(10,2) NOT NULL,
  `unitCost` decimal(10,2) NOT NULL,
  `totalCost` decimal(10,2) NOT NULL,
  `shopId` int NOT NULL,
  `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `productId` (`productId`),
  KEY `purchase_items_purchase_idx` (`purchaseId`),
  KEY `purchase_items_shop_idx` (`shopId`),
  CONSTRAINT `PurchaseItems_ibfk_1` FOREIGN KEY (`purchaseId`) REFERENCES `Purchases` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `PurchaseItems_ibfk_2` FOREIGN KEY (`productId`) REFERENCES `Products` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `PurchaseItems_ibfk_3` FOREIGN KEY (`shopId`) REFERENCES `Shops` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=67 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

