--
-- Table structure for table `Purchases`
--

DROP TABLE IF EXISTS `Purchases`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Purchases` (
  `id` int NOT NULL AUTO_INCREMENT,
  `referenceNo` varchar(255) NOT NULL,
  `supplierName` varchar(255) NOT NULL,
  `supplierContact` varchar(255) DEFAULT NULL,
  `purchaseDate` datetime NOT NULL,
  `status` enum('RECEIVED','PENDING','CANCELLED') DEFAULT 'RECEIVED',
  `paymentStatus` enum('PAID','PARTIAL','UNPAID') DEFAULT 'PAID',
  `paymentMethod` varchar(255) DEFAULT 'CASH',
  `totalAmount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `notes` text,
  `items` json NOT NULL,
  `shopId` int NOT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `supplierId` int DEFAULT NULL,
  `paidAmount` decimal(10,2) NOT NULL DEFAULT '0.00',
  PRIMARY KEY (`id`),
  UNIQUE KEY `referenceNo` (`referenceNo`),
  UNIQUE KEY `purchases_shop_reference_unique` (`shopId`,`referenceNo`),
  KEY `purchases_shop_id` (`shopId`),
  KEY `Purchases_supplierId_foreign_idx` (`supplierId`),
  CONSTRAINT `Purchases_ibfk_2` FOREIGN KEY (`shopId`) REFERENCES `Shops` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `Purchases_supplierId_foreign_idx` FOREIGN KEY (`supplierId`) REFERENCES `Suppliers` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=76 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

