CREATE TABLE `SaleItems` (
  `id` int NOT NULL AUTO_INCREMENT,
  `shopId` int NOT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `saleId` int NOT NULL,
  `productId` int NOT NULL,
  `quantity` int NOT NULL,
  `price` decimal(10,2) DEFAULT NULL,
  `originalPrice` decimal(10,2) DEFAULT NULL,
  `discountType` enum('percentage','fixed') DEFAULT NULL,
  `discountValue` decimal(10,2) DEFAULT NULL,
  `taxRate` decimal(5,2) NOT NULL DEFAULT '0.00',
  `taxAmount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `notes` text,
  `metadata` json DEFAULT NULL,
  `returnReason` varchar(255) DEFAULT NULL,
  `serialNumber` varchar(255) DEFAULT NULL,
  `batchNumber` varchar(255) DEFAULT NULL,
  `discount` decimal(10,2) DEFAULT '0.00',
  `unitPrice` decimal(10,2) DEFAULT NULL,
  `subtotal` decimal(10,2) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_sale_items_product_id` (`productId`),
  KEY `idx_sale_items_sale_id` (`saleId`),
  KEY `sale_items_shop_id` (`shopId`),
  KEY `idx_saleItems_saleId` (`saleId`),
  KEY `idx_saleItems_productId` (`productId`) USING BTREE,
  CONSTRAINT `SaleItems_ibfk_28` FOREIGN KEY (`shopId`) REFERENCES `Shops` (`id`),
  CONSTRAINT `SaleItems_ibfk_29` FOREIGN KEY (`saleId`) REFERENCES `Sales` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `SaleItems_ibfk_30` FOREIGN KEY (`productId`) REFERENCES `Products` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=554 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
