DROP TABLE IF EXISTS `SalePayments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `SalePayments` (
  `id` int NOT NULL AUTO_INCREMENT,
  `saleId` int NOT NULL,
  `amount` decimal(10,2) NOT NULL,
  `paymentMethod` varchar(50) NOT NULL,
  `paymentReference` varchar(255) DEFAULT NULL,
  `paymentProvider` varchar(255) DEFAULT NULL,
  `status` enum('pending','completed','failed','refunded') DEFAULT 'completed',
  `processedBy` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `metadata` json DEFAULT NULL,
  `shopId` int NOT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `gatewayRef` varchar(200) DEFAULT NULL,
  `paidAt` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_payments_sale_id` (`saleId`),
  KEY `idx_payments_status` (`status`),
  KEY `idx_sale_payments_processed_by` (`processedBy`),
  KEY `shopId` (`shopId`),
  CONSTRAINT `fk_salepayments_processedBy` FOREIGN KEY (`processedBy`) REFERENCES `Employees` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `SalePayments_ibfk_1` FOREIGN KEY (`saleId`) REFERENCES `Sales` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=213 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
