--
-- Table structure for table `SaleRefunds`
--

DROP TABLE IF EXISTS `SaleRefunds`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `SaleRefunds` (
  `id` int NOT NULL AUTO_INCREMENT,
  `saleId` int NOT NULL,
  `amount` decimal(10,2) NOT NULL,
  `reason` text,
  `refundMethod` enum('cash','card','mobile_money','store_credit') NOT NULL DEFAULT 'cash',
  `processedBy` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `status` enum('pending','processed','failed') DEFAULT 'processed',
  `metadata` json DEFAULT NULL,
  `shopId` int NOT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `productId` int DEFAULT NULL,
  `quantity` int DEFAULT '0',
  `refundAmount` decimal(10,2) DEFAULT NULL,
  `refundedBy` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `refundedAt` datetime DEFAULT NULL,
  `disposition` enum('restock','damaged_writeoff','return_to_supplier') DEFAULT 'restock',
  `reasonCode` enum('DEFECTIVE','WRONG_ITEM','EXPIRED','CHANGED_MIND','OTHER') DEFAULT 'OTHER',
  `reasonNotes` text,
  `managerApprovalId` varchar(36) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `processedBy` (`processedBy`),
  KEY `idx_refunds_sale_id` (`saleId`),
  KEY `idx_refunds_status` (`status`),
  KEY `shopId` (`shopId`),
  KEY `productId` (`productId`),
  CONSTRAINT `SaleRefunds_ibfk_25` FOREIGN KEY (`saleId`) REFERENCES `Sales` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `SaleRefunds_ibfk_26` FOREIGN KEY (`shopId`) REFERENCES `Shops` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `SaleRefunds_ibfk_27` FOREIGN KEY (`productId`) REFERENCES `Products` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=57 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

