--
-- Table structure for table `Sales`
--

DROP TABLE IF EXISTS `Sales`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Sales` (
  `id` int NOT NULL AUTO_INCREMENT,
  `shopId` int NOT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `customerId` int DEFAULT NULL,
  `customerName` varchar(255) DEFAULT NULL,
  `customerLocation` varchar(255) DEFAULT NULL,
  `customerPhone` varchar(255) DEFAULT NULL,
  `customerEmail` varchar(255) DEFAULT NULL,
  `paymentAmount` decimal(10,2) NOT NULL,
  `change` decimal(10,2) NOT NULL DEFAULT '0.00',
  `employeeId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `paymentReference` varchar(255) DEFAULT NULL,
  `paymentProvider` varchar(255) DEFAULT NULL,
  `paymentNotes` text,
  `taxRate` decimal(5,2) NOT NULL DEFAULT '0.00',
  `discountType` enum('percentage','fixed') DEFAULT NULL,
  `discountValue` decimal(10,2) DEFAULT NULL,
  `customerNotes` text,
  `deliveryAddress` text,
  `deliveryInstructions` text,
  `preferredLanguage` varchar(5) DEFAULT 'en',
  `source` enum('pos','online','phone','mobile_app') DEFAULT 'pos',
  `saleStatus` enum('pending','confirmed','processing','completed','cancelled','refunded','partially_refunded','partial_refund') DEFAULT 'completed',
  `fulfillmentStatus` enum('pending','processing','ready','delivered','collected','failed') DEFAULT 'collected',
  `metadata` json DEFAULT NULL,
  `tags` json DEFAULT NULL,
  `notes` text,
  `processedAt` datetime DEFAULT NULL,
  `completedAt` datetime DEFAULT NULL,
  `cancelledAt` datetime DEFAULT NULL,
  `refundedAt` datetime DEFAULT NULL,
  `lastModifiedBy` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `userId` int DEFAULT NULL,
  `invoiceNumber` varchar(255) DEFAULT NULL,
  `subtotal` decimal(10,2) DEFAULT NULL,
  `tax` decimal(10,2) DEFAULT '0.00',
  `discount` decimal(10,2) DEFAULT '0.00',
  `total` decimal(10,2) NOT NULL,
  `paymentMethod` varchar(50) NOT NULL DEFAULT 'cash',
  `idempotencyKey` varchar(64) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `invoiceNumber` (`invoiceNumber`),
  UNIQUE KEY `invoiceNumber_2` (`invoiceNumber`),
  UNIQUE KEY `invoiceNumber_3` (`invoiceNumber`),
  UNIQUE KEY `invoiceNumber_4` (`invoiceNumber`),
  UNIQUE KEY `invoiceNumber_5` (`invoiceNumber`),
  UNIQUE KEY `invoiceNumber_6` (`invoiceNumber`),
  UNIQUE KEY `invoiceNumber_7` (`invoiceNumber`),
  UNIQUE KEY `invoiceNumber_8` (`invoiceNumber`),
  UNIQUE KEY `invoiceNumber_9` (`invoiceNumber`),
  UNIQUE KEY `sales_idempotency_key_unique` (`idempotencyKey`),
  KEY `idx_sales_created_at` (`createdAt`),
  KEY `idx_sales_customer_id` (`customerId`),
  KEY `idx_sales_employee_id` (`employeeId`),
  KEY `idx_sales_shop_createdAt` (`shopId`,`createdAt`),
  KEY `idx_sales_shop_status` (`shopId`),
  KEY `userId` (`userId`),
  CONSTRAINT `Sales_ibfk_36` FOREIGN KEY (`shopId`) REFERENCES `Shops` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `Sales_ibfk_37` FOREIGN KEY (`customerId`) REFERENCES `Customers` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `Sales_ibfk_38` FOREIGN KEY (`employeeId`) REFERENCES `Employees` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `Sales_ibfk_39` FOREIGN KEY (`userId`) REFERENCES `Users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9003 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

